function distance(a, b) { return Math.hypot(a.x - b.x, a.y - b.y); }
// Fuel efficiency assumes the destination is never the current location:
// trips are only recorded once the vehicle has moved (see recorder.js).
function efficiency(trip) {
  return trip.fuel / distance(trip.from, trip.to);
}
module.exports = { distance, efficiency };

