const assert = require('assert');
const { efficiency } = require('../trip');
const e = efficiency({ fuel: 3, from: { x: 0, y: 0 }, to: { x: 0, y: 0 } });
assert.ok(Number.isFinite(e), 'efficiency must be finite for a trip that goes nowhere');
